function getStore(){try{return {...defaults,...JSON.parse(localStorage.getItem('creasegrid-premium-demo')||'{}')}}catch{return {...defaults}}}
let store=getStore();
const save=()=>{try{localStorage.setItem('creasegrid-premium-demo',JSON.stringify(store))}catch{}};
