function allArticles(){return [...store.publishedNews,...seedArticles]}
function toast(text){const el=$('#toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
function currentPath(){const h=location.hash.replace(/^#/,'');return h.startsWith('/')?h:'/' }
function link(href,text,cls=''){return `<a href="#${href}" class="${cls}">${text}</a>`}
function brand(sub=false){return `<a href="#/" class="brand" aria-label="CreaseGrid homepage"><span class="brand-symbol"></span><span class="brand-name">CreaseGrid</span>${sub?'<small>Global Cricket Intelligence<br>from Pakistan</small>':''}</a>`}
function header(){let r=state.route;return `<header class="site-header ${state.mobileMenu?'open':''}"><div class="container header-inner">${brand(true)}<nav class="nav" aria-label="Main navigation">${nav.map(([p,n])=>link(p,n,r===p||(p!=='/'&&r.startsWith(p+'/'))?'active':'' )).join('')}</nav><div class="header-actions"><button class="icon-btn" data-action="open-search" aria-label="Search">${ic('search')}</button><a class="btn ghost slim" href="#/my-cricket">My Cricket</a><a class="btn primary slim" href="#/organizer">Get Started</a><button class="icon-btn menu-button" data-action="toggle-menu" aria-label="Toggle menu">${ic(state.mobileMenu?'close':'menu')}</button></div></div></header><div class="demo-strip"><b>INTERACTIVE DESIGN PROTOTYPE</b> · Scores, rankings, news and statistics are sample data, not real-time coverage.</div>`}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div>${brand(false)}<div class="footer-desc">Built in Pakistan for the global cricket community. Understand the game through useful tools, clear stories and accessible local cricket technology.</div></div><div><h4>Explore</h4>${link('/matches','Match Centre')}${link('/tournaments','Tournaments')}${link('/player','Players')}${link('/stats','Records')}</div><div><h4>Tools</h4>${link('/tools/run-rate','Run Rate')}${link('/tools/net-run-rate','Net Run Rate')}${link('/qualification','Qualification Lab')}${link('/tools','All Tools')}</div><div><h4>Community</h4>${link('/local','Local Cricket')}${link('/organizer','Organizer Workspace')}${link('/my-cricket','My Cricket')}${link('/organizer/scoring','Demo Scoring')}</div><div><h4>Stories</h4>${link('/news','Cricket News')}${link('/news/world-cup-explained','Explainers')}${link('/news/t20-reset','Analysis')}${link('/admin','Admin Preview')}</div></div><div class="footer-bottom"><span>© 2026 CreaseGrid · Prototype for evaluation and development</span><span>Sample content · No live API · No real user authentication</span></div></div></footer>`}
function sectionHead(title,url,label='View all'){return `<div class="section-head"><h2>${title}</h2>${url?link(url,`${label} ${ic('arrow','tiny')}`,'section-link'):''}</div>`}
function crumbs(nodes){return `<div class="breadcrumb">${link('/','Home')}${nodes.map(([u,t])=>`${ic('chevron','tiny')}${u?link(u,esc(t)):`<span>${esc(t)}</span>`}`).join('')}</div>`}
function matchTile(m){return `<a class="match-tile" href="#/matches/${m.slug}" aria-label="${esc(m.name)}, demo match"><div><div class="match-teams">${m.af} ${m.a} <span class="muted">vs</span> ${m.b} ${m.bf}</div><small>${m.detail} · DEMO</small></div><div class="score-mini">${m.as}<span>${m.bs||'Match not started'}</span></div>${ic('chevron','tiny')}</a>`}
function newsRow(a){return `<div class="news-row"><div class="grow"><span class="chip blue row-tag">${esc(a.category)}</span><h4><a href="#/news/${a.id}">${esc(a.title)}</a></h4><div class="xs muted">${esc(a.stamp)} · ${a.minutes} min read</div></div>${ic('chevron','tiny')}</div>`}
function sidePointTable(){return `<div class="table-scroller"><table class="mini-table"><thead><tr><th>#</th><th>Team</th><th>P</th><th>Pts</th><th>NRR</th></tr></thead><tbody>${standings(demoTeams).map((t,i)=>`<tr class="${i<2?'qualify':''}"><td>${i+1}</td><td>${t.flag} ${t.name}</td><td>${t.p}</td><td><b>${t.pts}</b></td><td>${signed(nrr(t))}</td></tr>`).join('')}</tbody></table></div>`}
